import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"35、【晋】 坤下离上","description":"周易阐真 - 35、【晋】 坤下离上","frontmatter":{"title":"35、【晋】 坤下离上","description":"周易阐真 - 35、【晋】 坤下离上"},"headers":[],"relativePath":"zh/classics/chanzhen/036.md","filePath":"zh/classics/chanzhen/036.md"}'),s={name:"zh/classics/chanzhen/036.md"};function n(c,p,i,o,h,l){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：晋，进也，明出地上。顺而丽乎大明，柔进而上行，是以康侯用锡马蕃庶，昼日三接也。</p></blockquote><h1 id="_35、【晋】-坤下离上" tabindex="-1">35、【晋】 坤下离上 <a class="header-anchor" href="#_35、【晋】-坤下离上" aria-label="Permalink to “35、【晋】 坤下离上”">​</a></h1><p>初六：晋如摧如，贞吉。罔孚，裕，无咎。</p><p>六二：晋如愁如，贞吉。受兹介福，于其王母。</p><p>六三：众允，悔亡。</p><p>九四：晋如鼫鼠，贞厉。</p><p>六五：悔亡，失得勿恤。往吉，无不利。</p><p>上九：晋其角，维用伐邑。厉吉，无咎，贞吝。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：明出地上，晋。君子以自昭明德。</p><p>晋者，进也。上离日，下坤地，是日出地上也。日本明，地本暗，明出地上，由暗而明，晋之象也。</p><p>君子有见于此，知日入于地，又能出地；人昧其德，亦能明德。以是自昭其明德焉。昭者，明也。明德者，即人本来良知良能之灵性。此性本来真空妙有，炯炯不昧，一交后天气质之性，由明入暗，失其本体矣。但不明由于自，昭明亦由于自，是在自昭不昭耳。若果自知昭明，即便能明，急须下手修为，除去一切积滞，解脱万般尘情，从实地上用工夫，戒慎恐惧，防微杜渐，人心自去，道心自彰，气质自化，真性自现，仍是当年圆陀陀、光灼灼、净倮倮、赤洒洒一个虚灵不昧物事了也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>鼫，音石。</p><p>晋者，进也。卦德上离明，下坤顺，由顺而生明，用明而行顺，顺时顺理，其明日增，故谓晋。此自诚而明，进火之卦，承上遁卦而来。遁者，止其健，而不轻用健也。不轻用健则心虚，心虚则烛照觉察，戒慎恐惧，不为物欲所瞒，黑中有白，神明自来矣。</p><p>人之本来良知良能之性，炯炯不昧，其德本明。因交后天，识神用事，人心起而道心藏，良知之健，变为不良之健，良能之顺，变为不良之顺。心与物交，锢闭灵窍，神明有昧矣。</p><p>圣人教人进火者，由不明而复进于明耳。进明之功，非顺道不能。顺者，顺时顺理，常存道心，不生人心，知之能之，无一不良。天之赋人者良，人之顺天者亦良。天人合发，元神不昧，自诚而明，其明日增，由小而大，自微而著，渐进于高明远见之处，有象于康侯，用锡马蕃庶，昼日三接也。</p><p>康侯者，安泰宁静之侯。马在午，属于离明之象。蕃庶者，地所生，属于坤顺之象。昼日者，日之明，明在上也。三接者，地之顺，顺在下也。</p><p>人之良知良能之真心，为一身之主，如一国之有康侯也。真心不背于天良，用明用顺，如康侯用锡马蕃庶也。</p><p>由顺而生明，以明而行顺，如昼日三接也。三接者，乃再三之顺，不顺而必至于顺，其中有闲邪存诚之功。闲邪存诚，人心顺、道心彰，诚则明矣，明则诚矣。诚明兼该，明明德而止于止善，进火之功尽矣。</p><p>初六，在明之初，大理未明，宜静不宜动，是以晋如摧如，守贞而吉也。夫守贞而吉者，以其未能自信，先须穷理，充裕于内，运火自无差错之咎矣。此未进明、先求其明也。</p><p>六二，处于三阴昏暗之中，不但不能增明，而且有以蔽明，是以晋如愁如也。然柔而守正，不为假阴所惑，不进而亦不愁，是以贞而得吉。盖能贞则致虚守静，真阴现象，假阴自化，如受兹介福于其王母矣。此处不明、不遽进明也。</p><p>六三，不能自下而顺，乃自上而顺，似乎不正而致悔。然性柔志刚，不顺阴而顺阳，借他家之明，以济我家之暗，我顺他而他即顺我，是以众允其进，有悔可亡。此己不明、顺人之明也。</p><p>九四，居于明体，已进于明矣。但在二阴之内，明藏暗中，又应初阴，明而有私，邪正不分，是非相杂，以是进明如鼫鼠夜行，所见不大，其行不远。虽用明得正，终有危厉。此刚而有私之明也。</p><p>六五，居于二阳之内，既明其我家不明，又明其他家有明，借刚济柔，本有悔者而悔可亡。悔由于心之不虚，若知虚心，则以己求人，即能实腹。既实其腹，则吉凶止足，如在掌上，可以失得勿恤，直行无疑，往而进火下功，吉无不利者。此虚以招实之明也。</p><p>上九，刚强自胜，只知进明，不知虚明，是以维用伐邑也。邑为私邑，伐邑即克己之功。克己之功，虚人心也。若不虚心，独恃其刚，强制强伏，必危厉而后得吉，得无咎。以是用明，虽克己得正，亦属勉强，不由自然，未免取吝于大方。此刚而高亢之明也。</p><p>然则进明运火之道，未明必先求其明，既明又当虚其明，虚实并用，刚柔相当。自诚而明，明本于诚，其明日进日高，用之不尽，取之不竭，大地里黄芽长遍，满世界金花开绽，无处不可用明，无处能伤其明矣。</p>',27)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
